WITH matrix AS (PIVOT (SELECT date_trunc('month',refunded_at AT TIME ZONE 'UTC')::DATE AS mon,reason,qty::BIGINT AS qty FROM returns WHERE status='refunded' AND refunded_at>=TIMESTAMPTZ '2024-01-01 00:00:00+00' AND refunded_at<TIMESTAMPTZ '2025-01-01 00:00:00+00') ON reason IN ('damaged','wrong_item','unwanted') USING sum(qty) GROUP BY mon) SELECT mon,coalesce(damaged,0)::BIGINT AS damaged,wrong_item::BIGINT AS wrong_item,coalesce(unwanted,0)::BIGINT AS unwanted FROM matrix ORDER BY mon;
